/**
 * Owned blocks in shared CSV files (PLAN.md §6 rule 4): generated rows go between marker comment
 * rows; re-export replaces only that block; rows outside blocks (hand-written) are never changed.
 *
 *   # sagaforge:begin <key> hash=<hash> (generated by Saga Forge; edits here are overwritten),,,,,,
 *   ...rows...
 *   # sagaforge:end <key>,,,,,,
 *
 * Markers are unquoted with "#" in column 1, so the game's CSV parser skips them in every file
 * (docs/FORMATS.md, "CSV comments"). The hash covers the rows between the markers, so a hand edit
 * inside a block is noticed before it would be overwritten.
 */
import { parseCsvRecords, csvCell } from '../csvedit'
import { parseRulesCsvRows } from './csvrows'
import type { RuleRow } from '../rules/types'

export interface Block {
  key: string
  /** Hash written in the begin marker (what Saga Forge exported). */
  hash: string
  /** Offsets: begin marker start, end marker end (with its line break). */
  start: number
  end: number
  /** The rows between the markers, exactly as in the file. */
  body: string
}

const BEGIN = /^#\s*sagaforge:begin\s+(\S+)(?:\s+hash=([0-9a-f]+))?/
const END = /^#\s*sagaforge:end\s+(\S+)/

/** FNV-1a 32-bit over the text with line endings normalized: stable across platforms, no Node needed. */
export function blockHash(body: string): string {
  const t = body.replace(/\r\n/g, '\n').replace(/\n+$/, '')
  let h = 0x811c9dc5
  for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0 }
  return h.toString(16).padStart(8, '0')
}

export function findBlocks(text: string): Block[] {
  const recs = parseCsvRecords(text)
  const out: Block[] = []
  let open: { key: string; hash: string; start: number; bodyStart: number } | null = null
  for (let i = 0; i < recs.length; i++) {
    const r = recs[i]
    const first = r.raw[0] ?? ''
    const b = BEGIN.exec(first)
    if (b) { open = { key: b[1], hash: b[2] ?? '', start: r.start, bodyStart: nextLine(text, r.end) }; continue }
    const e = END.exec(first)
    if (e && open && e[1] === open.key) {
      out.push({ key: open.key, hash: open.hash, start: open.start, end: nextLine(text, r.end), body: text.slice(open.bodyStart, r.start) })
      open = null
    }
  }
  return out
}

function nextLine(text: string, i: number): number {
  if (text.startsWith('\r\n', i)) return i + 2
  if (text[i] === '\n') return i + 1
  return i
}

export type BlockState = 'new' | 'same' | 'changed' | 'edited-by-hand'

/**
 * Put `rows` (CSV lines, without line breaks) into the block `key`. Returns the new text and what
 * happened. When the block was edited by hand, the text is returned unchanged unless `force`.
 */
export function writeBlock(text: string, key: string, rows: string[], columns: number, opts: { force?: boolean; eol?: string } = {}): { text: string; state: BlockState } {
  const eol = opts.eol ?? (text.includes('\r\n') ? '\r\n' : '\n')
  const body = rows.map((r) => r + eol).join('')
  const hash = blockHash(body)
  const pad = ','.repeat(Math.max(0, columns - 1))
  const begin = `# sagaforge:begin ${key} hash=${hash} (generated by Saga Forge; edits here are overwritten)${pad}${eol}`
  const end = `# sagaforge:end ${key}${pad}${eol}`
  const block = findBlocks(text).find((b) => b.key === key)
  if (!block) {
    const sep = text.length && !text.endsWith('\n') ? eol : ''
    return { text: text + sep + begin + body + end, state: 'new' }
  }
  if (block.hash && blockHash(block.body) !== block.hash && !opts.force) return { text, state: 'edited-by-hand' }
  if (blockHash(block.body) === hash && block.hash === hash) return { text, state: 'same' }
  return { text: text.slice(0, block.start) + begin + body + end + text.slice(block.end), state: 'changed' }
}

/** Remove a block (when its quest is deleted). */
export function removeBlock(text: string, key: string): string {
  const b = findBlocks(text).find((x) => x.key === key)
  return b ? text.slice(0, b.start) + text.slice(b.end) : text
}

/** "Detach": the block becomes hand-written (markers removed, rows kept). */
export function detachBlock(text: string, key: string): string {
  const b = findBlocks(text).find((x) => x.key === key)
  return b ? text.slice(0, b.start) + b.body + text.slice(b.end) : text
}

/** The text with every owned block cut out (the hand-written part). */
export function outsideBlocks(text: string): string {
  let out = ''
  let pos = 0
  for (const b of findBlocks(text)) { out += text.slice(pos, b.start); pos = b.end }
  return out + text.slice(pos)
}

/** The mod's hand-written rules (rows outside owned blocks). */
export function handRules(rulesCsv: string | undefined, sourceId: string): RuleRow[] {
  if (!rulesCsv) return []
  return parseRulesCsvRows(outsideBlocks(rulesCsv), sourceId, 'data/campaign/rules.csv')
}

/** One CSV line from cells. */
export const csvLine = (cells: string[]) => cells.map((c) => csvCell(c ?? '')).join(',')
